pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 lockTime, uint256 collectAmount) public {
        // bound inputs to admissible range
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        lockTime = bound(lockTime, 0, 365 days);
        collectAmount = bound(collectAmount, 1, depositAmount);

        // setup: initialize contract and set MinSum
        vm.prank(address(0x1234));
        c.SetMinSum(0);
        vm.prank(address(0x1234));
        c.SetLogFile(address(0xdead));
        vm.prank(address(0x1234));
        c.Initialized();

        // actor makes deposit
        address actor = address(0xB0B);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(lockTime);

        // record balance after Put
        (, uint256 balanceAfterPut) = c.Acc(actor);

        // warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // prepare to collect
        vm.deal(actor, 0);  // for call gas, actor already has eth from vm.deal before Put
        vm.prank(actor);

        // attempt collect and check if it succeeded
        bool ok;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        if (ok) {
            // after successful collect, balance should have decreased by collectAmount
            (, uint256 balanceAfterCollect) = c.Acc(actor);
            // General rule: balance after Collect == balance after Put - collectAmount
            assertTrue(balanceAfterCollect == balanceAfterPut - collectAmount);
        } else {
            // if Collect failed, balance should remain unchanged
            (, uint256 balanceAfterCollect) = c.Acc(actor);
            assertTrue(balanceAfterCollect == balanceAfterPut);
        }
    }
}

