import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 putValue, uint256 lockTime, uint256 collectAmt) public {
        // Bound inputs to practical, admissible ranges
        putValue = bound(putValue, 1, 1000 ether);
        lockTime = bound(lockTime, 0, 365 days);
        collectAmt = bound(collectAmt, 1, 1000 ether);

        // Setup sender
        address user = address(0x1234);
        vm.deal(user, putValue);

        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Put with value
        vm.prank(user);
        c.Put{value: putValue}(lockTime);

        // Advance time past unlock
        vm.warp(block.timestamp + lockTime + 1);

        // Record balance before Collect
        uint256 balBefore = c.Acc(user).balance;

        // Attempt Collect
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            uint256 balAfter = c.Acc(user).balance;
            // Under correct Put (addition), the new balance must be non-negative after subtraction.
            // Buggy Put uses subtraction, leading to assertion failure (revert) when collectAmt > diminished balance.
            // For success, the reference ensures no arithmetic underflow: balAfter >= 0 by safe math.
            assertTrue(balAfter >= 0);
        } else {
            // If it reverted, skip assertion for this path.
            assertTrue(true);
        }
    }
}

