pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        // Bound deposits to avoid overflow in the contract's safe math and keep values reasonable
        deposit1 = bound(deposit1, 1, 1e24);
        deposit2 = bound(deposit2, 1, 1e24);
        // collectAmt must not exceed total deposited amount to allow Collect to succeed
        collectAmt = bound(collectAmt, 1, deposit1 + deposit2);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Set up actor with enough Ether
        address actor = address(0x1);
        uint256 totalDeposited = deposit1 + deposit2;
        vm.deal(actor, totalDeposited);

        // Perform two Put calls (both add Ether to the contract and update balance)
        vm.prank(actor);
        c.Put{value: deposit1}(0);
        vm.prank(actor);
        c.Put{value: deposit2}(0);

        // Record contract Ether balance after all deposits but before Collect
        uint256 contractBalanceAfterDeposits = address(c).balance;

        // Warp past unlock time so Collect can succeed
        vm.warp(block.timestamp + 1);

        // Attempt Collect
        vm.prank(actor);
        c.Collect(collectAmt);

        // After a successful Collect, the contract's Ether balance plus the amount collected
        // must equal the total Ether sent via Put. The bug makes Put subtract, so this invariant fails.
        assertEq(address(c).balance + collectAmt, contractBalanceAfterDeposits);
    }
}

