pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit, uint256 lockTime, uint256 collectAmt) public {
        // Constrain amounts to avoid overflow in safe math (sub_uint256/add_uint256 asserts)
        deposit = bound(deposit, 0, type(uint256).max / 2);
        collectAmt = bound(collectAmt, 0, type(uint256).max / 2);
        lockTime = bound(lockTime, 0, type(uint256).max / 2);

        // Setup: initialize contract, set MinSum to 0 to allow any collect
        address alice = address(0x100);
        vm.deal(alice, deposit + 1 ether);
        vm.startPrank(alice);

        c.SetMinSum(0);
        c.SetLogFile(address(0x200));
        c.Initialized();

        // Put with deposit
        c.Put{value: deposit}(lockTime);

        // Warp past unlock time
        uint256 unlock = deposit == 0 ? 0 : block.timestamp + lockTime + 1;
        vm.warp(unlock);

        // Try to Collect
        bool ok = false;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // If Collect succeeded, the caller's balance must be >= collectAmt (fundamental invariant of sub_uint256)
        if (ok) {
            uint256 bal = c.Acc(alice).balance;
            assertTrue(bal >= collectAmt);
        } else {
            // If Collect failed, the balance must be < collectAmt (or other condition not met)
            uint256 bal = c.Acc(alice).balance;
            assertTrue(bal < collectAmt || block.timestamp <= c.Acc(alice).unlockTime);
        }

        vm.stopPrank();
    }
}

